import "fmt"

func typeOf(v any) string {
	switch x := v.(type) {
	case string:
		return "string:" + x
	case int:
		return "int"
	case bool:
		return "bool"
	default:
		return fmt.Sprintf("%T", x)
	}
}

func main() {
	fmt.Println(typeOf("go"), typeOf(7), typeOf(true), typeOf(1.5))
}

